 for(const invalid of [
  source.replace(/^selectionUses='lowpolyLumine',?\r?\n/m,''),
  source.replace("selectionUses='lowpolyLumine'","selectionUses='battle133'"),
  source.replace(/^lowpolyLumine=.*\r?\n/m,''),
